import{z as B,x as l,o as E,c as s,q as n,j as i,D as e,d as A,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"实证挑战与理论的回应","description":"","frontmatter":{"title":"实证挑战与理论的回应","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-empirical-challenges.md","filePath":"econ/apt-empirical-challenges.md","lastUpdated":1791063341000}'),c={name:"econ/apt-empirical-challenges.md"};function h(m,a,p,d,D,f){const t=l("Mermaid");return E(),s("div",null,[a[2]||(a[2]=n('<h1 id="实证挑战与理论的回应" tabindex="-1">实证挑战与理论的回应 <a class="header-anchor" href="#实证挑战与理论的回应" aria-label="Permalink to &quot;实证挑战与理论的回应&quot;">​</a></h1><div class="epigraph"><p>理论在黑板上从不输，输在资产定价的检验协议里：一桩联合假设、一串多重比较、一次发表之后的衰减。</p><footer>—— 据 Fama, *Journal of Finance* 1970；Harvey, Liu and Zhu, *RFS* 2016；McLean and Pontiff, *JF* 2016 整理</footer></div><p><a href="/econ/apt-behavioral-deep">上一课</a>摆出三个弯曲核的手术台，并写明各自欠的证据。本课收账：候选模型在数据前怎么判。工具链的一半已经存在——<a href="/quant/fama-macbeth">Fama–MacBeth 截面回归</a>、<a href="/econ/gmm-econ">GMM 矩检验</a>、<a href="/econ/hansen-jagannathan">Hansen–Jagannathan 界</a>、<a href="/econ/shiller-excess-volatility">过度波动</a>与<a href="/econ/dp-ratio-predictability">股利-价格比预测</a>。缺口是把它们串成流水线，再看几十年的异象清单如何反过来重塑理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>资产定价的检验生来是联合假设：定价模型与市场有效性捆在一起（Fama 1970，见<a href="/econ/emh">市场有效性</a>），拒绝时分不清账该记在哪边。第二重困难是多重性：几十年间发表的因子数以百计，按 5% 名义水平筛，必然捞出真伪混合的一批。第三重是适应性：因子一旦发表就被人交易，溢价本身会衰减。三重困难叠加的后果是：不设协议，「发现」的存量不可信；设了协议，理论必须换一种方式回应数据。</p><p><span class="marginnote">Harvey–Liu–Zhu 2016 清点了 316 个已发表因子：在多重检验之下，新因子的 t 统计量门槛应从习惯的 1.96 抬到 3.0 以上；McLean–Pontiff 2016 给出市场侧的对应证据——因子收益在发表后平均衰减约 58%。「门槛抬高」与「发现即衰减」是同一枚硬币的两面。</span></p><p><span class="marginnote">「联合假设」翻译成白话：你一次检验的其实是「定价模型正确」加「市场有效」两个捆在一起的命题。统计上拒绝时只能说「至少有一个错了」，却分不清该记在哪一边——这一刀切不开，是资产定价检验的先天限制，不是做得不够仔细。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四道工序。第一，时序与截面分工：GRS 检验（Gibbons–Ross–Shanken 1989）在时序上问「截距是否共同为零」，<a href="/quant/fama-macbeth">Fama–MacBeth</a> 在截面上问「定价误差是否与贝塔排成一条线」——两条腿缺一条，横截面拟合就能靠因子之间的相关性蒙混。第二，矩与界：GMM 直接检验 \\(1=E[mR]\\)，Hansen–Jagannathan 距离报「离可行集多远」，与参数化无关。第三，异象清单：规模与账面市值比（Fama–French 1992、1993）、动量及其后数百个因子；多重比较按<a href="/econ/multiple-testing-econ">多重检验</a>的纪律校正，规格自由度按<a href="/econ/pm-specification-map">实证设计规范与收束</a>登记。第四，衰减诊断：McLean–Pontiff 2016 报样本外衰减约四分之一、发表后约 58%；Hou–Xue–Zhang 2020 在计入微观结构成本后，多数异象不再显著。</p>',9)),(E(),i(r,null,{default:e(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MODEL%5B%22%E5%80%99%E9%80%89%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20TS%5B%22%E6%97%B6%E5%BA%8F%3A%20GRS%20%E6%88%AA%E8%B7%9D%E8%81%94%E5%90%88%E6%A3%80%E9%AA%8C%22%5D%0A%20%20MODEL%20--%3E%20CS%5B%22%E6%88%AA%E9%9D%A2%3A%20Fama%E2%80%93MacBeth%20%E6%8E%92%E7%BA%BF%22%5D%0A%20%20MODEL%20--%3E%20MM%5B%22%E7%9F%A9%E4%B8%8E%E7%95%8C%3A%20GMM%20%2F%20HJ%20%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20TS%20--%3E%20ZOO%5B%22%E5%BC%82%E8%B1%A1%E6%B8%85%E5%8D%95%E4%B8%8E%E5%A4%9A%E9%87%8D%E6%A3%80%E9%AA%8C%E9%97%A8%E6%A7%9B%22%5D%0A%20%20CS%20--%3E%20ZOO%0A%20%20MM%20--%3E%20ZOO%0A%20%20ZOO%20--%3E%20DECAY%7B%22%E5%8F%91%E8%A1%A8%E5%90%8E%E8%BF%98%E5%89%A9%E5%A4%9A%E5%B0%91%3F%22%7D%0A%20%20DECAY%20--%3E%7C%22%E5%89%A9%E5%BE%97%E5%A4%9A%22%7C%20KEEP%5B%22%E8%BF%9B%E5%85%A5%E6%9C%BA%E5%88%B6%E4%B9%8B%E4%BA%89%22%5D%0A%20%20DECAY%20--%3E%7C%22%E5%89%A9%E5%BE%97%E5%B0%91%22%7C%20DEAD%5B%22%E8%AE%B0%E4%B8%BA%E6%95%B0%E6%8D%AE%E6%8C%96%E6%8E%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>协议如何反过来重塑理论。条件化：让贝塔与核随状态移动（Lettau–Ludvigson 2001 的 cay）确实能救一些模型，但 Lewellen–Nagel 2006 显示条件 CAPM 的时变不足以解释动量与横截面——救不到头。特征对协方差：Daniel–Titman 1997 问「值的是特征还是贝塔」，把解释义务从协方差压到公司层变量上。载体替换：<a href="/econ/intermediary-asset-pricing">中介资产定价</a>、<a href="/econ/demand-system-asset-pricing">需求系统资产定价</a>与<a href="/econ/production-based-asset-pricing">生产基础的资产定价</a>各自换掉「消费边际效用」这个默认载体。Cochrane 2011 用 <a href="/econ/campbell-shiller-decomposition">Campbell–Shiller 分解</a>把横截面按现金流消息与折现率消息重新记账：异象不再是待消灭的「谜」，而是期望收益时变结构的清单——本课程前六课正是给这份清单配机制。</p><p>第一张图画的是检验流水线：数据怎么审模型。这一张画反方向：被数据拒绝之后，理论有哪些退路、三条路又如何汇入对异象的同一份重读。</p>',3)),(E(),i(r,null,{default:e(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E6%A8%AA%E6%88%AA%E9%9D%A2%E6%8B%92%E7%BB%9D%EF%BC%9A%E5%8D%95%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%E6%8E%92%E4%B8%8D%E6%88%90%E7%BA%BF%22%5D%20--%3E%20COND%5B%22%E6%9D%A1%E4%BB%B6%E5%8C%96%EF%BC%9A%CE%B2%20%E4%B8%8E%E6%A0%B8%E9%9A%8F%E7%8A%B6%E6%80%81%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20FAIL%20--%3E%20FEAT%5B%22%E7%89%B9%E5%BE%81%E5%AF%B9%E5%8D%8F%E6%96%B9%E5%B7%AE%EF%BC%9A%E5%80%BC%E7%9A%84%E6%98%AF%E7%89%B9%E5%BE%81%E8%BF%98%E6%98%AF%20%CE%B2%EF%BC%9F%22%5D%0A%20%20FAIL%20--%3E%20CARR%5B%22%E8%BD%BD%E4%BD%93%E6%9B%BF%E6%8D%A2%EF%BC%9A%E6%8D%A2%E6%8E%89%E6%B6%88%E8%B4%B9%E8%BE%B9%E9%99%85%E6%95%88%E7%94%A8%22%5D%0A%20%20COND%20--%3E%20RE%5B%22%E5%BC%82%E8%B1%A1%E9%87%8D%E8%AF%BB%E4%B8%BA%E6%9C%9F%E6%9C%9B%E6%94%B6%E7%9B%8A%E7%9A%84%E6%97%B6%E5%8F%98%E7%BB%93%E6%9E%84%22%5D%0A%20%20FEAT%20--%3E%20RE%0A%20%20CARR%20--%3E%20RE%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">数字实例：假设 100 个候选因子彼此独立、全都毫无真溢价，按 5% 的名义门槛筛选，平均也会「发现」约 5 个假因子。t 门槛从 1.96 抬到 3.0 不是苛刻，是给这种「翻车率」上保险——翻车的候选越多，单次检验的名义水平就得越紧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>协议只保证拒绝的语义，不生产理论；候选名单仍由想象力供给。发表偏置与数据挖掘无法被完全校正，复制对数据商与处理细节敏感——Hou–Xue–Zhang 的复现争议说明连「异象是否存在」都依赖处理口径。衰减诊断有自己的样本期问题：近年登记的因子还没走完发表后窗口，现在断言「都衰减了」为时过早。判别设计的选择本身是自由度，登记在案才不沦为又一次规格搜索。</p><p><span class="marginnote">为什么重要：假如你按一篇论文的回测把真金白银押上去，而溢价在发表后平均衰减约 58%，策略上线后的表现会远低于回测。发表滞后不是技术细节，而是回测可信度的「折旧率」——读任何异象论文都要先问：这是税前还是税后、是发表前还是发表后。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检验生来是联合假设；时序（GRS）与截面（Fama–MacBeth）两条腿必须同时走。</li><li>HJ 距离与 GMM 提供与参数化无关的拒绝口径；多重检验把 t 门槛抬到 3.0 以上。</li><li>发表后衰减约 58% 是市场学习的证据；「门槛抬高」与「发现即衰减」互为印证。</li><li>理论的回应是条件化、特征化与载体替换；异象清单被重读为期望收益的时变结构。</li><li>出处：Fama and MacBeth, <em>JPE</em> 1973；Gibbons, Ross and Shanken, <em>Econometrica</em> 1989；Harvey, Liu and Zhu, <em>RFS</em> 2016；McLean and Pontiff, <em>JF</em> 2016；Cochrane, <em>JF</em> 2011。</li></ul>',6))])}const u=B(c,[["render",h]]);export{C as __pageData,u as default};
